//! Error type for the pa-falcon-rotator driver.
//!
//! The Falcon's failure modes are the shared transport-driver common core
//! plus one of the driver's own: a `Sync` whose record cannot be written.
//! The enum, its ASCOM classification, `From<TransportError>`, and the
//! `Result` alias are all generated by [`rusty_photon_driver::driver_error!`].
//! The codec-layer `From<SessionError<FalconCodecError>>` lives in
//! [`crate::codec`] and targets this (local) enum.

rusty_photon_driver::driver_error! {
    /// Errors that can occur when interacting with the Pegasus Falcon Rotator.
    pub enum FalconRotatorError {
        /// `Sync` could not write the sync-offset record, so the offset in
        /// force is unchanged (design doc §The sync-offset record).
        #[error("the sync offset could not be saved: {0}")]
        SyncNotSaved(String),
    }
}
